namespace Mode.Domain.Entities;

/// <summary>Belongs to exactly one channel or one conversation (enforced by a check constraint).</summary>
public class Message
{
    /// <summary>Generated by the client so retried sends are idempotent.</summary>
    public Guid Id { get; set; }

    public Guid? ChannelId { get; set; }
    public Guid? ConversationId { get; set; }

    /// <summary>One level of threading: a reply's parent is always a top-level message.</summary>
    public Guid? ParentMessageId { get; set; }

    /// <summary>Monotonic per room (channel or conversation), shared by top-level messages and replies.</summary>
    public long Sequence { get; set; }

    /// <summary>Room sequence of the latest change (create, edit, delete, reaction, new reply); drives reconnect replay.</summary>
    public long UpdatedSequence { get; set; }

    public required string AuthorUserId { get; set; }

    /// <summary>Set for webhook posts; the author is then "bot:{webhookId}" rather than a host user.</summary>
    public string? BotName { get; set; }

    public required string BodyMarkdown { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset? EditedAt { get; set; }
    public DateTimeOffset? DeletedAt { get; set; }
    public string? DeletedByUserId { get; set; }

    public int ReplyCount { get; set; }
    public DateTimeOffset? LastReplyAt { get; set; }

    /// <summary>Server-made copy of a forwarded message. It can't be edited, so the forward card can't be faked.</summary>
    public string? ForwardedBodyMarkdown { get; set; }
    public Guid? ForwardedFromMessageId { get; set; }
    public string? ForwardedFromUserId { get; set; }
    public DateTimeOffset? ForwardedFromCreatedAt { get; set; }

    public Channel? Channel { get; set; }
    public Conversation? Conversation { get; set; }
    public Message? Parent { get; set; }
    public List<MessageEdit> Edits { get; set; } = [];
    public List<Reaction> Reactions { get; set; } = [];
    public List<Mention> Mentions { get; set; } = [];
    public List<MessageAttachment> Attachments { get; set; } = [];
    public PinnedMessage? Pin { get; set; }
}

public class PinnedMessage
{
    public Guid MessageId { get; set; }
    public required string PinnedByUserId { get; set; }
    public DateTimeOffset PinnedAt { get; set; }

    public Message? Message { get; set; }
}

/// <summary>Prior body text kept for compliance. Authors may see their own earlier edits; deleted text is never shown to users.</summary>
public class MessageEdit
{
    public Guid Id { get; set; }
    public Guid MessageId { get; set; }
    public MessageChangeKind Kind { get; set; }
    public required string PreviousBodyMarkdown { get; set; }
    public required string ChangedByUserId { get; set; }
    public DateTimeOffset ChangedAt { get; set; }

    public Message? Message { get; set; }
}

public class Reaction
{
    public Guid MessageId { get; set; }
    public required string UserId { get; set; }
    public required string Emoji { get; set; }
    public DateTimeOffset CreatedAt { get; set; }

    public Message? Message { get; set; }
}

public class Mention
{
    public Guid Id { get; set; }
    public Guid MessageId { get; set; }
    public MentionKind Kind { get; set; }

    /// <summary>Set only when <see cref="Kind"/> is <see cref="MentionKind.User"/>.</summary>
    public string? TargetUserId { get; set; }

    public Message? Message { get; set; }
}
